s=dict(action='continue',rationale='Select a source-defined current-term election support discriminator from the authority backbone.',map_path='campaign-votes-map.json',map_changes=changes,question=q,feedback=dict(ref_ids=['S_campaign','S_send','S_candidate_follower','S_step','S_tracker_votes','S_roles'],answered='Vote replies use explicit campaign terms. send delays real/self vote replies behind local storage, while candidate support stores only first boolean per sender. Real candidacy resets that map and increments term; Step drops lower-term ordinary responses before state dispatch. The next check can independently compare actual original reply terms with leadership, rather than reading the vote map as its own oracle.',remaining=['Construct two real campaigns and fix the current-term grant condition for fresh formal execution.'],understanding='updated',rationale='This offers an applicable local eligibility duty and a concrete stale/current discriminator, unlike the paused configuration contract ambiguity.'))
